// Claude's review tests for A12 (call sequences). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { buildInput } from './handler';
import { pickStep } from './sequence';
import { newProject, type Mock, type MockResponse, type MockSequence } from './types';

const step = (status: number, body: string): MockResponse => ({ status, headers: {}, body, bodyEncoding: 'text', delayMs: 0 });

describe('pickStep', () => {
  const steps = [step(202, 'a'), step(202, 'b'), step(200, 'c')];
  it('stay: call N gets step N, then the last one forever', () => {
    const s: MockSequence = { steps, after: 'stay' };
    expect([1, 2, 3, 4, 9].map((n) => pickStep(s, n).body)).toEqual(['a', 'b', 'c', 'c', 'c']);
  });
  it('loop: starts over after the last', () => {
    const s: MockSequence = { steps, after: 'loop' };
    expect([1, 2, 3, 4, 5, 6, 7].map((n) => pickStep(s, n).body)).toEqual(['a', 'b', 'c', 'a', 'b', 'c', 'a']);
  });
  it('a count below 1 is the first call', () => {
    expect(pickStep({ steps, after: 'loop' }, 0).body).toBe('a');
    expect(pickStep({ steps, after: 'stay' }, -3).body).toBe('a');
  });
});

describe('buildInput callCount', () => {
  const m: Mock = {
    id: 'm', enabled: true, method: 'ANY', urlPattern: '/x', response: step(200, ''), source: 'manual', createdAt: 0,
  };
  it('is passed to the code as req.callCount', () => {
    expect(buildInput(m, { method: 'GET', url: 'http://a.test/x', headers: {}, callCount: 3 }).req.callCount).toBe(3);
  });
  it('is 1 when not given', () => {
    expect(buildInput(m, { method: 'GET', url: 'http://a.test/x', headers: {} }).req.callCount).toBe(1);
  });
});

describe('export and import carry sequences', () => {
  function withSeq(seq: unknown): string {
    const p = newProject('p', 'http://a.test');
    p.scenarios[0]!.mocks.push({
      id: 'm', enabled: true, method: 'GET', urlPattern: '/x', response: step(200, ''), source: 'manual', createdAt: 0,
      reply: 'sequence', sequence: seq as MockSequence,
    });
    return exportProject(p);
  }
  it('round-trips a sequence', () => {
    const seq: MockSequence = { steps: [step(202, 'a'), step(200, 'b')], after: 'loop' };
    const r = parseProjectFile(withSeq(seq));
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.sequence).toEqual(seq);
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.reply).toBe('sequence');
  });
  it('rejects a bad sequence', () => {
    expect(parseProjectFile(withSeq({ steps: [step(200, 'a')], after: 'sometimes' })).ok).toBe(false);
    expect(parseProjectFile(withSeq({ steps: [{ status: 'x' }], after: 'stay' })).ok).toBe(false);
    expect(parseProjectFile(withSeq({ steps: 'no', after: 'stay' })).ok).toBe(false);
  });
});
